class Solution {
    public int strStr(String haystack, String needle) {
        int m = haystack.length();
        int n = needle.length();
        if (n == 0) {
            return 0;
        }
        if (n > m) {
            return -1;
        }

        int[] lps = new int[n];
        for (int i = 1, len = 0; i < n; ) {
            if (needle.charAt(i) == needle.charAt(len)) {
                lps[i++] = ++len;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }

        for (int i = 0, j = 0; i < m; ) {
            if (haystack.charAt(i) == needle.charAt(j)) {
                i++;
                j++;
                if (j == n) {
                    return i - n;
                }
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return -1;
    }
}

class Solution {
    public int strStr(String haystack, String needle) {
        int m = haystack.length();
        int n = needle.length();
        if (n == 0) {
            return 0;
        }
        if (n > m) {
            return -1;
        }

        for (int i = 0; i <= m - n; i++) {
            int j = 0;
            while (j < n && haystack.charAt(i + j) == needle.charAt(j)) {
                j++;
            }
            if (j == n) {
                return i;
            }
        }
        return -1;
    }
}

class Solution {
    public int strStr(String haystack, String needle) {
        int m = haystack.length();
        int n = needle.length();
        if (n == 0) {
            return 0;
        }
        if (n > m) {
            return -1;
        }

        long mod = 1_000_000_007L;
        long base = 256L;
        long power = 1L;
        long needleHash = 0L;
        long windowHash = 0L;

        for (int i = 0; i < n; i++) {
            needleHash = (needleHash * base + needle.charAt(i)) % mod;
            windowHash = (windowHash * base + haystack.charAt(i)) % mod;
            if (i + 1 < n) {
                power = (power * base) % mod;
            }
        }

        for (int start = 0; start <= m - n; start++) {
            if (needleHash == windowHash && matchesAt(haystack, needle, start)) {
                return start;
            }
            if (start < m - n) {
                windowHash = (windowHash - haystack.charAt(start) * power) % mod;
                if (windowHash < 0) {
                    windowHash += mod;
                }
                windowHash = (windowHash * base + haystack.charAt(start + n)) % mod;
            }
        }
        return -1;
    }

    private boolean matchesAt(String haystack, String needle, int start) {
        for (int i = 0; i < needle.length(); i++) {
            if (haystack.charAt(start + i) != needle.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public int strStr(String haystack, String needle) {
        int m = haystack.length();
        int n = needle.length();
        if (n == 0) {
            return 0;
        }
        if (n > m) {
            return -1;
        }

        String combined = needle + "#" + haystack;
        int[] z = new int[combined.length()];
        int left = 0;
        int right = 0;

        for (int i = 1; i < combined.length(); i++) {
            if (i <= right) {
                z[i] = Math.min(right - i + 1, z[i - left]);
            }
            while (i + z[i] < combined.length()
                    && combined.charAt(z[i]) == combined.charAt(i + z[i])) {
                z[i]++;
            }
            if (i + z[i] - 1 > right) {
                left = i;
                right = i + z[i] - 1;
            }
            if (z[i] == n) {
                return i - n - 1;
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public int strStr(String haystack, String needle) {
        int m = haystack.length();
        int n = needle.length();
        if (n == 0) {
            return 0;
        }
        if (n > m) {
            return -1;
        }

        int[] shift = new int[256];
        Arrays.fill(shift, n);
        for (int i = 0; i < n - 1; i++) {
            shift[needle.charAt(i)] = n - 1 - i;
        }

        int start = 0;
        while (start <= m - n) {
            int j = n - 1;
            while (j >= 0 && haystack.charAt(start + j) == needle.charAt(j)) {
                j--;
            }
            if (j < 0) {
                return start;
            }
            start += shift[haystack.charAt(start + n - 1)];
        }
        return -1;
    }
}
